import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            sum += a[i];
        }
        long base = sum / n, deficit = 0, excess = 0;
        // Final piles are base or base+1: missing below base vs. surplus above base+1.
        for (long v : a) {
            deficit += Math.max(0, base - v);
            excess += Math.max(0, v - base - 1);
        }
        System.out.println(Math.max(deficit, excess));
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	sum := int64(0)
	for i := range a {
		a[i] = nextInt()
		sum += a[i]
	}
	base := sum / int64(n)
	deficit, excess := int64(0), int64(0)
	// Final piles are base or base+1: missing below base vs. surplus above base+1.
	for _, v := range a {
		deficit += max(0, base-v)
		excess += max(0, v-base-1)
	}
	fmt.Println(max(deficit, excess))
}
